package com.technova.model;
import jakarta.persistence.*;
@Entity @Table(name="proveedor") public class Proveedor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_proveedor") private Long id; @Column(name="razon_social") private String razonSocial; private String ruc,contacto,telefono,email,direccion; private Boolean estado; public Proveedor(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getRazonSocial(){return razonSocial;} public void setRazonSocial(String v){razonSocial=v;} public String getRuc(){return ruc;} public void setRuc(String v){ruc=v;} public String getContacto(){return contacto;} public void setContacto(String v){contacto=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getDireccion(){return direccion;} public void setDireccion(String v){direccion=v;} public Boolean getEstado(){return estado;} public void setEstado(Boolean v){estado=v;} }
